catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
   var eventDate = g_form.getValue('event_date');
    if (!eventDate) {
        alert('Please select Event Date first.');
        g_form.setValue('location', '');
        return;
    }

    var ga = new GlideAjax('x_1790227_event_ma.CheckLocationAvailability');
    ga.addParam('sysparm_name', 'checkLocationAvailability');
    ga.addParam('sysparm_location', newValue);
    ga.addParam('sysparm_event_date', eventDate);

    ga.getXMLAnswer(function(response) {
        if (response == 'false') {
            alert('This Location is already booked on the selected date. Please choose another.');
            g_form.setValue('location', '');
        }
    });

   //Type appropriate comment here, and begin script below

}
